<?php require_once 'includes/bootstrap.php'; if(current_user()) redirect('dashboard.php'); $errors=[];$email=trim($_POST['email']??''); if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf())$errors[]='Security check failed.';if(!validate_email($email))$errors[]='Please enter a valid email address.';$pass=$_POST['password']??'';if(!$errors){$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($pass,$u['password_hash']))$errors[]='Incorrect email or password.';else{if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT)){$h=password_hash($pass,PASSWORD_DEFAULT);$db=db();$x=$db->prepare('UPDATE users SET password_hash=? WHERE id=?');$x->execute([$h,$u['id']]);}login_user($u);$next=$_GET['redirect']??'dashboard.php';if(str_starts_with($next,'http'))$next='dashboard.php';redirect($next);}}} page_head('Log in','Securely log in to your Learn with Nazmul account.');site_header('login.php');render_flash(); ?>
<main><section class="narrow"><div class="form-card"><p class="section-label">WELCOME BACK</p><h1>Log in</h1><?php if($errors): ?><div class="alert error" role="alert"><ul><?php foreach($errors as $x): ?><li><?= e($x) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-group"><label for="email">Email</label><input id="email" type="email" name="email" required value="<?= e($email) ?>" autocomplete="email"></div><div class="form-group"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password"></div><button class="button primary-button" type="submit">Log in</button></form><p class="form-note">New learner? <a href="<?= e(url('register.php')) ?>">Create an account</a>.</p></div></section></main><?php site_footer(); ?>